output_text:
[
  {
    "id": "borrowed_cart_return_bay",
    "text": "Anyone who takes a cart is obliged to return it to the front cart-return bay before leaving.",
    "abstraction": {
      "state_properties": {
        "front_cart_bay": "at(0,1)",
        "cart_at_front_bay": "cartAt(0,1)",
        "cart_returned_to_front_bay": {
          "and": [
            "front_cart_bay",
            "cart_at_front_bay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "front_cart_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_to_front_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_front_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are prohibited from leaving the store while still possessing a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart"
      },
      "events": {
        "exit_attempt": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_in_possession",
          "exit_attempt"
        ]
      }
    }
  },
  {
    "id": "cart_drop_only_front_bay",
    "text": "A cart may only be left at the designated front cart-return bay.",
    "abstraction": {
      "state_properties": {
        "front_cart_bay": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          {
            "not": "front_cart_bay"
          }
        ]
      }
    }
  },
  {
    "id": "after_cart_return_use_start_aisle",
    "text": "After returning a cart at the front bay, a shopper is obliged to rejoin the start aisle before exiting.",
    "abstraction": {
      "state_properties": {
        "front_cart_bay": "at(0,1)",
        "cart_returned_to_front_bay": {
          "and": [
            "at(0,1)",
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        },
        "start_aisle_entry": "at(0,5)"
      },
      "events": {
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "front_cart_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_to_front_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "return_cart_to_front_bay",
      "discharge": "start_aisle_entry"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Required shelf items must be picked up only while the shopper has a cart available to receive them.",
    "abstraction": {
      "state_properties": {
        "cart_available_for_goods": "hasCart"
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_item_pickup",
          {
            "not": "cart_available_for_goods"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "Shoppers are prohibited from walking or exiting while carrying goods by hand.",
    "abstraction": {
      "state_properties": {
        "goods_carried_by_hand": "handFull"
      },
      "events": {
        "locomotion_or_exit": {
          "pre": {
            "or": [
              "N",
              "S",
              "E",
              "W",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "goods_carried_by_hand",
          "locomotion_or_exit"
        ]
      }
    }
  },
  {
    "id": "bottom_exit_lane_cart_free",
    "text": "The bottom exit corridor may not be traversed eastward or exited through while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "bottom_exit_corridor": {
          "or": [
            "at(0,5)",
            "at(1,5)",
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_possession": "hasCart"
      },
      "events": {
        "eastward_or_exit_corridor_use": {
          "pre": {
            "or": [
              "E",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "bottom_exit_corridor",
          "cart_in_possession",
          "eastward_or_exit_corridor_use"
        ]
      }
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart is parked at the front return bay, shoppers are prohibited from picking up additional shelf items.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_front_return": "cartAt(0,1)"
      },
      "events": {
        "additional_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_parked_at_front_return",
          "additional_item_pickup"
        ]
      }
    }
  }
]
